ALTER TABLE public.account_connection_invitations ADD COLUMN intended_account_type text;
COMMENT ON COLUMN public.account_connection_invitations.intended_account_type IS 'Explicit patient extension of the existing secure invitation; NULL retains existing Provider/Facility behavior.';
GRANT SELECT(intended_account_type) ON public.account_connection_invitations TO authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='manage_account_invitation'; definition:=replace(definition,$s$_type NOT IN ('provider','facility')$s$,$s$_type NOT IN ('provider','facility','patient')$s$); definition:=replace(definition,'recipient_email,intended_type,token_hash','recipient_email,intended_type,intended_account_type,token_hash'); definition:=replace(definition,'lower(trim(_email)),_type,_hash',$s$lower(trim(_email)),CASE WHEN _type='patient' THEN 'facility' ELSE _type END,_type,_hash$s$); definition:=replace(definition,$s$(_i.intended_type='facility' AND w.account_type IN ('facility','hospital'))$s$,$s$(_i.intended_type='facility' AND coalesce(_i.intended_account_type,'facility')<>'patient' AND w.account_type IN ('facility','hospital')) OR (_i.intended_account_type='patient' AND w.account_type='private_pay')$s$); EXECUTE definition; END $$;
CREATE FUNCTION public.patient_trip_event_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE request_id uuid;patient_ws uuid;reference text;label text; BEGIN
 IF TG_TABLE_NAME='request_status_events' THEN request_id:=NEW.ride_request_id; label:=CASE WHEN NEW.to_state IN ('approved','confirmed') THEN 'Trip confirmed' WHEN NEW.to_state IN ('canceled','cancelled','declined') THEN 'Trip canceled or declined' END;
 ELSE request_id:=NEW.ride_request_id;label:=CASE WHEN NEW.status='completed' AND NEW.status IS DISTINCT FROM OLD.status THEN 'Trip completed' WHEN NEW.status IN ('canceled','cancelled') AND NEW.status IS DISTINCT FROM OLD.status THEN 'Trip canceled' WHEN NEW.scheduled_start_time IS NOT NULL AND NEW.scheduled_start_time IS DISTINCT FROM OLD.scheduled_start_time THEN 'Added to dispatch schedule' WHEN NEW.driver_id IS NOT NULL AND NEW.driver_id IS DISTINCT FROM OLD.driver_id AND NEW.status IN ('assigned','in_progress') THEN 'Driver assigned' WHEN NEW.status IN ('assigned','confirmed') AND NEW.status IS DISTINCT FROM OLD.status THEN 'Trip confirmed' END; END IF;
 IF label IS NULL OR request_id IS NULL THEN RETURN NEW; END IF;
 SELECT coalesce(r.patient_workspace_id,CASE WHEN w.account_type='private_pay' THEN r.workspace_id END),r.mfn_id INTO patient_ws,reference FROM public.ride_requests r LEFT JOIN public.workspaces w ON w.id=r.workspace_id WHERE r.id=request_id AND NOT r.is_test;
 IF patient_ws IS NULL THEN RETURN NEW; END IF;
 INSERT INTO public.notifications(user_id,type,title,body,ride_request_id,link) SELECT m.user_id,'trip_patient_event',label,coalesce(reference,'Trip request'),request_id,'/portal/requests' FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=patient_ws AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL; RETURN NEW; END $$;
CREATE TRIGGER patient_request_status_notice AFTER INSERT ON public.request_status_events FOR EACH ROW EXECUTE FUNCTION public.patient_trip_event_notification();
CREATE TRIGGER patient_trip_status_notice AFTER UPDATE OF status,scheduled_start_time,driver_id ON public.trips FOR EACH ROW EXECUTE FUNCTION public.patient_trip_event_notification();
REVOKE ALL ON FUNCTION public.patient_trip_event_notification() FROM PUBLIC,anon,authenticated;